window.RP_SESSION={"id":"S-e0349e6710b9","messages":[{"id":"RP-0227838","time":"2026-08-14T02:41:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"늦은 밤, 가델랏 허그는 언제나처럼 주점에서 맥주와 고기를 즐기고 있습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0227839","time":"2026-08-14T02:41:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"길드에 도착 한 뒤로부터, 정말이지 꾸준히도 들른 곳이라 이젠 제일 단골급으로 반겨주는 주인장이네요.","characters":["P-6a1a99e98a44"]},{"id":"RP-0227840","time":"2026-08-14T02:42:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“하하하, 그랬다니까. 정말이지 정신도 없어서는, 머리에는 불이 붙고~”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227841","time":"2026-08-14T02:43:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그가 여느때처럼 자신의 이야기를 떠벌리는 사이, 주인장은 능숙하게 시원한 생맥주 한 잔을 가득 채워 허그에게 다시 건넨줍니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0227842","time":"2026-08-14T02:44:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"오늘도 적당히만 마셔두라고. 아, 그리고 내가 밴드 하나를 섭외했는데 한번 봐볼래? 주점에 노래가 빠지면 섭섭하잖아?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227843","time":"2026-08-14T02:44:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“어엥? 밴드?”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227844","time":"2026-08-14T02:45:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"그래! 밴드말이야. 슬슬 올 때가 됐는데...\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227845","time":"2026-08-14T02:45:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“아- 여이, 저번에 위크씨가 주점에서 한 곡 쑀을때 여운이 굉장했었나보구만?”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227846","time":"2026-08-14T02:45:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"콰아아아앙-!!\n\n누군가가 허그의 단골 주점의 문을 발로 뻥차서 큰 소리로 열면서 뭐라 소리를 치네요. 무뢰배 같은 사람이 분명합니다.\n\n\"주인장! 여기 Kartoffelkuchen 파는가?\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0227847","time":"2026-08-14T02:46:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“???”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227848","time":"2026-08-14T02:46:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"무 뭐야! 그 기사 나으리인가? 허그! 또 그 친구를 부른거야?!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227849","time":"2026-08-14T02:47:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“어엥?? 아니, 저런 느낌의 요상함이 아니었었는데 말이야??“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227850","time":"2026-08-14T02:47:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"본인이 요리에는 재능이 없어서...감자 케이크 파는가 안파는가?\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0227851","time":"2026-08-14T02:47:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"몇일째 삶은 감자만 먹으니 물린다네 어서 감자로 만든 다른 음식은 없는겐가?\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0227852","time":"2026-08-14T02:48:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"그렇게 진상짓을 부리던 도중에 옆에 앉아 있는 이들을 확인합니다.","characters":["P-f6e62ae5e46d"]},{"id":"RP-0227853","time":"2026-08-14T02:48:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"어.. 그 감자는 있는뎁쇼... 감자 으깬거라도 드릴까요? 안주기는 한데...\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227854","time":"2026-08-14T02:48:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"어...그대들 반갑다네\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0227855","time":"2026-08-14T02:48:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이… 감자 양반…“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227856","time":"2026-08-14T02:49:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"감자가 아니라 기사라고 부르시게나\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0227857","time":"2026-08-14T02:49:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“주인장, 혹시 그쪽이 불렀다는 밴드가 감자 양반이었어? 확실히 요란하긴 한데 말이지.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227858","time":"2026-08-14T02:49:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"감자… 저자의 뒤에서 감자 후광이 보입니다…","characters":["P-6a1a99e98a44"]},{"id":"RP-0227859","time":"2026-08-14T02:49:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아니... 나는 저 기사분은 부르지도 않았는데...\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227860","time":"2026-08-14T02:50:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아니 근데 진짜로 슬슬 밴드가 올때가 됐는데...\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227861","time":"2026-08-14T02:50:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-f6e62ae5e46d"]},{"id":"RP-0227862","time":"2026-08-14T02:50:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"허그가 보는 모습은 대충 이런 모숩이겠죠","characters":["P-f6e62ae5e46d"]},{"id":"RP-0227863","time":"2026-08-14T02:50:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"크아아악…","characters":["P-6a1a99e98a44"]},{"id":"RP-0227864","time":"2026-08-14T02:51:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"그때! 다시 한번 문을 박차고...\n\n뻬르난떼가 등장했다!\n\n\"나의 아리따운 음악의 소리를 들을 평민들이어! 기뻐하라, 그리고 찬사하라!\"\n\n\"ㅁ뭐야!\"\n\n주인장은 크게 당황을 한 것 같았다.\n\n아무래도 오늘 부른 밴드는 뻬르난떼가 아닌 것 만큼은 확실했다.\n\n그리고 뻬르난떼의 뒤에서 주인장이 부른 밴드가 등판했고, 공연을 준비하기 시작했다...","characters":["P-1a1afae9c8db"]},{"id":"RP-0227865","time":"2026-08-14T02:51:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"여튼 감자를 으깨서 만든 메쉬드 포테이토를 투구 전면부를 재치고는 먹고 있었다.","characters":["P-f6e62ae5e46d"]},{"id":"RP-0227866","time":"2026-08-14T02:51:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"우리 주점 문 뿌셔지겠다 이 양반들아!!!","characters":["P-6a1a99e98a44"]},{"id":"RP-0227867","time":"2026-08-14T02:52:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"오늘 내가 부른 노래는 장난감의 꿈이노니. 이를 잘 듣는다면 그대들의 귀 건강과 안구 건강과 감동이 가득하고, 낭만이 있으며, 눈물이 가득한 이야기를 전해들을 수 있을 것이로다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227868","time":"2026-08-14T02:52:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"그리고 뻬르난떼는 음악 소리에 맞춰 노래를 부르기 시작했다...","characters":["P-1a1afae9c8db"]},{"id":"RP-0227869","time":"2026-08-14T02:52:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"파일: 정체를 알 수 없는 노래.mp3","characters":["P-1a1afae9c8db"]},{"id":"RP-0227870","time":"2026-08-14T02:52:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”어엥?“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227871","time":"2026-08-14T02:52:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"음...근데 저자도 기사인것인가? 갑옷을 입고 이긴 한데 말일세\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0227872","time":"2026-08-14T02:53:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"...뻬르난떼의 노래는 너무나도 처량했고, 잘 부르기는 했었으나 주점에 맞는 분위기는 아니였으니.\n\n주점의 술이 동나는 속도가 조금씩 느려지기 시작했다...","characters":["P-1a1afae9c8db"]},{"id":"RP-0227873","time":"2026-08-14T02:53:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"허그! 저 미치신 분좀 끌어내려봐! 이러다가 내 돈줄이 끊기겠어!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227874","time":"2026-08-14T02:54:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 그냥 어벙벙 할 뿐입니다.\n거 오늘도 진탕 마시긴 글렀네!","characters":["P-6a1a99e98a44"]},{"id":"RP-0227875","time":"2026-08-14T02:54:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"냠냠 쩜쩝 감자 맏있다.","characters":["P-f6e62ae5e46d"]},{"id":"RP-0227876","time":"2026-08-14T02:54:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 밴드와 뻬르난떼의 도통 어찌 반응해야할 지 모르는 하모니에 호응해보려 했으나, 이내 관뒀습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0227877","time":"2026-08-14T02:54:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"물론, 뻬르난떼는 그저 스카웃을 당했을 뿐인 선량 한 편력 기사였으나, 안타깝게도 뻬르난떼의 의견을 적극적으로 들어준 나머지 이와 같은 사태가 벌어지고 만 것이었다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0227878","time":"2026-08-14T02:55:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이~ 음… 잘한다~”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227879","time":"2026-08-14T02:55:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…주인장, 아무래도 그쪽 센스가 영…”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227880","time":"2026-08-14T02:55:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"뻬르난떼는 마침내 열창을 하기 시작했고...\n\n주점 주인은 점차 표정이 썩어들어가기 시작했다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0227881","time":"2026-08-14T02:55:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"저 놈은 내가 부른게 아니야....\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227882","time":"2026-08-14T02:57:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"그리고 노래가 다 끝났을 무렵.\n\n\"아, 이 나의 노래를 끝까지 들어주다니. 스포트라이트가 나를 환하게 비추는구나. 이 어찌도 밝지 아니 할 수 있겠는고? 이제 나는 그만 나의 수행을 위하여 이곳을 빠져나가겠나이니. 귀족들의 연회는 내가 없더라도 결코 끝나지 않으리다.\"\n\n뻬르난떼는 허그에게 윙크(물론 갑옷에 가려져서 보이진 않았을 것이다.)를 한 뒤, 주점 밖으로 나왔다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0227883","time":"2026-08-14T02:57:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"모든 주점 손님들은 어안이 벙벙 한 채로 가만히 있었고...\n\n밴드는 이내 드디어 주점에 맞는 연주를 하기 시작했다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0227884","time":"2026-08-14T02:57:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“끄하……“\n\n허그는 제 이마를 살짝 짚었습니다.\n아무래도 같이 목표를 함께하기로 동료 관계인 경이 대뜸 찾아와 저러고 가버렸으니 말입니다.\n부끄러움은 허그의 몫이란 말인가…","characters":["P-6a1a99e98a44"]},{"id":"RP-0227885","time":"2026-08-14T02:58:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"...허그. 저런 남자한테 홀라당 넘어가면 안돼.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227886","time":"2026-08-14T02:58:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…미안하구만, 나도 이만 가봐야겠어. 아무래도 눈이라도 마주친 것 같아서 말이야.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227887","time":"2026-08-14T02:58:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“어엥?? 여이, 누가 넘어간다고!”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227888","time":"2026-08-14T02:58:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"파일: star wars cantina.mp3","characters":["P-1a1afae9c8db"]},{"id":"RP-0227889","time":"2026-08-14T02:59:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"알맞은 주점 노래.","characters":["P-1a1afae9c8db"]},{"id":"RP-0227890","time":"2026-08-14T02:59:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"어쩔 수 없지. 잘 가고. 그리고 저기 계신 기사분은... 우리 집 감자 요리를 다 끝장내실 생각이시구만?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227891","time":"2026-08-14T02:59:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“아 참, 그러고 보면 말이야, 길드 식구들도 그렇고 주인장도 그렇고, 왜 다들 요상한 소리를 자꾸 해대는 걸까나.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227892","time":"2026-08-14T03:00:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“경이랑 내가 동료 관계라고 몇번을 말해도 다들 듣질 않는다고…”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227893","time":"2026-08-14T03:00:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“특히 마리아!”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227894","time":"2026-08-14T03:00:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"하하, 허그. 원래 대다수의 사람들이 비슷한 말을 해댄다는 것은 그 말이 사실에 가깝다는 말이야. 제3자가 보기에는 말이지?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227895","time":"2026-08-14T03:00:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"솔직히, 너도 누가 나를 보면서 왕자님, 거리면서 내가 위기에 빠지거나 뭘 할때마다 졸졸 따라와서 도와주면 너는 내가 개랑 사귄다고 생각하지 않겠어?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227896","time":"2026-08-14T03:01:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”어… 여이, 그건 아무래도…!“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227897","time":"2026-08-14T03:01:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"그래! 그런거야!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227898","time":"2026-08-14T03:01:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”경이랑 얘기를 해봐야 할려나? 뻬르난떼 경은 아무렇지도 않은가봐.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227899","time":"2026-08-14T03:02:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"뭣?! 너한테 공주님이라 할 정도면 이미 너를 사랑하고 있는거 아니였어?! 그럼 진짜로 사귀는 사이가 아니였다고??\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227900","time":"2026-08-14T03:02:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그건 또 무슨 소리냐고 여이!!!”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227901","time":"2026-08-14T03:03:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"당연히 너가 부끄러워서 거짓말을 하고 있는줄 알았지...\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227902","time":"2026-08-14T03:03:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“아잇, 나 가!”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227903","time":"2026-08-14T03:03:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"음.. 어... 그래.. 잘 가고.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227904","time":"2026-08-14T03:03:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 대뜸 자리를 박차고 일어나 주점 밖으로 사라집니다…","characters":["P-6a1a99e98a44"]},{"id":"RP-0227905","time":"2026-08-14T03:04:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"허그가 주점 밖에 나오자...\n\n뻬르난떼는 보이지 않았다.\n\n이미 길드로 간 것이었을까?","characters":["P-1a1afae9c8db"]},{"id":"RP-0227906","time":"2026-08-14T03:04:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“끄하으, 다들 왜그러는 거냐고~!\n나는 나대로 진지하게 경을 도우려고 그러는건데 말이야, 우리가 무슨 일을 하고있는지 다들 모를거라고.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227907","time":"2026-08-14T03:06:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 그러고 보니 경은 어느정도 얻은게 있으려나? 난 그동안 딱히 뭐가 없었는데…”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227908","time":"2026-08-14T03:07:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"요근래 캠프에 한 번씩 들를 때마다, 허그는 맥도귈이라는 이름을 가진 사람에 대해서 몇번씩 묻고 다니곤 했다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0227909","time":"2026-08-14T03:07:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그러나 다들 사막에만 말뚝박고 사는 토박이들이라 그런건지, 종자에 대한 소식은 감감 무소식! 다들 맥도귈이라는 자에 대해 아는 것은 전혀 없었다—!","characters":["P-6a1a99e98a44"]},{"id":"RP-0227910","time":"2026-08-14T03:08:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“음~ 뻬르난떼 경은 먼저 갔나?”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227911","time":"2026-08-14T03:09:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"길드로 돌아가시겠읍니까?","characters":["P-1a1afae9c8db"]},{"id":"RP-0227912","time":"2026-08-14T03:09:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"돌아가겠읍니다~","characters":["P-6a1a99e98a44"]},{"id":"RP-0227913","time":"2026-08-14T03:09:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"투타타타타…","characters":["P-6a1a99e98a44"]},{"id":"RP-0227914","time":"2026-08-14T03:10:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아! 공주님. 마침내 여왕폐하의 길드에 당도하셨군요. 반갑습니다. 주점에서의 저의 감동 있고, 교훈 가득하며, 아리따운 노래는 어떠하셨나이까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227915","time":"2026-08-14T03:12:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이~ 경이구만! 아까 당황해서는 인사라도 못한게 미안하네~\n노래는… 음…”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227916","time":"2026-08-14T03:12:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"!매력","characters":["P-6a1a99e98a44"]},{"id":"RP-0227917","time":"2026-08-14T03:12:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'가델랏 허그'의 매력 판정 :\n[2] + [-1] = [1]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-0227918","time":"2026-08-14T03:13:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 혼신을 다해 뻬르난떼의 노래가 괜찮았으나 다음엔 좀 더 신나는 노래로 불러보면 어떠겠냐는 식의 말을 전했다…!","characters":["P-6a1a99e98a44"]},{"id":"RP-0227919","time":"2026-08-14T03:13:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 아무튼 그렇다고~ 노래는 괜찮았어!”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227920","time":"2026-08-14T03:14:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아, 제가 귀족들의 연회라는 것에 너무나도 심취 한 나머지 너무나도 정적인 노래를 부른 것 같군요. 이에 대해서는 제 사과의 말씀을 전하겠나이다. 아무튼.... 아직 연회는 끝나지 않았을 터인데 어째서 이리도 일찍 오시게 되셨습니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227921","time":"2026-08-14T03:17:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”하하하, 아쉽게도 말이야.\n뭔가 술이 막~ 들어가려는 참에 아는 얼굴이 밖으로 나가는걸 봐버렸구만~\n그것도 뻬르난떼 경인데 말이야, 내가 안따라가고 버티겠어? 여이!“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227922","time":"2026-08-14T03:18:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아, 공주님께서 저를 위해 따라 와 주시다니. 이러한 공주님의 은혜에 어찌 할 방도를 느끼지 못하겠군요! 물론, 편력 기사의 매력은 능히 빠져나올 수 없었을 터이지만 말입니다. 그렇다면 공주님께서도 제가 거기서 노래를 하게 됀 경위에 대한 이야기를 해 드려도 되는지 여쭈어 봐도 되겠습니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227923","time":"2026-08-14T03:19:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이! 당연하지, 그것도 궁금했었고 말이야~“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227924","time":"2026-08-14T03:20:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”이렇게 서서 얘기하기엔 불편하니까 말이야, 어디 앉거나 들어가서라도 얘기하자고, 오늘 의뢰를 잘못 다녀온건지 다리가 아프네…“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227925","time":"2026-08-14T03:20:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아아, 제가 노래를 하게 됀 경위는 제가 길을 거닐다가 은혜로운 곳에서 자작시를 낭독하며 노래를 부르고 있었나이니. 그때 그 밴드가 저를 종용하여 저에게 부디 한곡이라도 불러 달라며 부탁을 하게 되었나이다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227926","time":"2026-08-14T03:20:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아, 그러시지요. 여기, 모닥불을 지펴드리도록 하겠나이니. 비록 누추하오만 이곳에 앉아주시옵소서.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227927","time":"2026-08-14T03:21:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"뻬르난떼는 모닥불을 지피기 시작했다...","characters":["P-1a1afae9c8db"]},{"id":"RP-0227928","time":"2026-08-14T03:21:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"!모닥불","characters":["P-1a1afae9c8db"]},{"id":"RP-0227929","time":"2026-08-14T03:21:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"모닥불에 불씨가 옮겨 붙습니다.\n따뜻한 온기가 피어오릅니다.\n\n ♩ https://youtu.be/3GNyTB6p6i0?si=4L6Rg34M-gtWRqUj","characters":[]},{"id":"RP-0227930","time":"2026-08-14T03:21:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"다리가 아프시다면 이 제가 공주님의 다리를 마사지를 해 드려도 되겠습니까? 저 돈 뻬르난떼 데 일리아는 아파서 드러 누운 자도 일어나게 만들 지식이 있나이니!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227931","time":"2026-08-14T03:22:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“읏차~ 하하, 불 좋네!“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227932","time":"2026-08-14T03:22:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”여이, 정말로? 그정도란 말이야?”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227933","time":"2026-08-14T03:22:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"물론이옵니다! 이 저 돈 뻬르난떼는 결코 거짓말을 하지 않나이니.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227934","time":"2026-08-14T03:23:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"그렇다면 잠시 실례를 하도록 하겠나이다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227935","time":"2026-08-14T03:23:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“오오…“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227936","time":"2026-08-14T03:23:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"뻬르난떼는 허그의 다리를 마사지 해 주기 시작했다...","characters":["P-1a1afae9c8db"]},{"id":"RP-0227937","time":"2026-08-14T03:23:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-1a1afae9c8db"]},{"id":"RP-0227938","time":"2026-08-14T03:23:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'돈 뻬르난떼 데 일리아'의 지능 판정 :\n[10] + [1] = [11]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0227939","time":"2026-08-14T03:23:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그럼 어디 한 번 받아봐야겠구만, 하하하~“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227940","time":"2026-08-14T03:24:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"뻬르난떼는 허그의 뭉친 부위들을 성공적으로 풀어줬다!\n\n\"이리 한다면 공주님의 고통이 싹 날아가실 터. 어떻습니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227941","time":"2026-08-14T03:25:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 편히 마사지를 받으며 이야기를 이어갔습니다.\n이런 맙소사, 내가 날고 있나요!","characters":["P-6a1a99e98a44"]},{"id":"RP-0227942","time":"2026-08-14T03:25:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“끄하~~ 여이, 굉장하잖아 뻬르난떼 경!\n어떻게 아픈 곳만 잘 골라서 풀어줬어, 고맙구만~”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227943","time":"2026-08-14T03:26:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"왓.\n\n\"편력 기사인 제가 어찌 아픈 자를 외면 할 수 있겠나이까? 이는 당연 한 의무이노니. 너무 감사하실 필요는 없나이다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227944","time":"2026-08-14T03:27:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그래도 굉장한건 굉장하다고 해야하는 거라고? 뭔가 이쯤되니 경은 못하는게 뭘까 싶은걸~”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227945","time":"2026-08-14T03:28:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“아무튼, 그럼 밴드 녀석들은 어떤 시를 들었길래 그렇게까지 한거래?”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227946","time":"2026-08-14T03:28:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"하하! 허나, 저는 그저 미천한 미물이노니. 이 제가 어찌 못 하는게 없을수가 있겠습니까? 그럼에도, 편력 기사로서 인간이 할 수 있는 범위에는 최대한 닿기 위한 노력을 하고 있을 뿐이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227947","time":"2026-08-14T03:29:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아, 그 시의 내용은...\"\n\n아까 뻬르난떼가 불렀었던 노래의 가사와 크게 다르지 않은 것 같았다.\n\n사실상 뻬르난떼의 노래를 두번이나 들은 허그였다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0227948","time":"2026-08-14T03:29:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"오어… 반복재생이다…","characters":["P-6a1a99e98a44"]},{"id":"RP-0227949","time":"2026-08-14T03:29:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이~ 아까 그거네? 주점에서 불렀던.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227950","time":"2026-08-14T03:30:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"맞습니다! 역시, 공주님께서 똘똘하신 덕분에 기억력이 좋으시군요.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227951","time":"2026-08-14T03:30:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그럼 그 녀석들은 제대로 부른 경한테 왜 그런 표정을 지은거람? 앞뒤가 다른 녀석들이네!“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227952","time":"2026-08-14T03:31:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"허나, 그들은 제가 부탁한 노래를 잘 들려주었나이니. 이는 필히 현장의 분위기로 인해서 그런 것이었을 터 이옵니다. 그러니 공주님께서도 너무 화를 내지 말아주시길.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227953","time":"2026-08-14T03:34:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아무튼... 공주님께서는 무언가 하고 싶으신 말이 있으실거 같은 표정이오시니. 저의 앞에서는 궃이 하고 싶으신 말을 뒤에 숨기실 필요가 없나이다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227954","time":"2026-08-14T03:36:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그렇다면야 뭐…“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227955","time":"2026-08-14T03:36:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”아, 맞다. 이 얘기를 할려고 왔었지.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227956","time":"2026-08-14T03:37:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”경은 아직 기억하지? 우리가 같이 경의 종자? 인가 하는 아이를 찾기로 한거 말이야.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227957","time":"2026-08-14T03:37:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아! 맞습니다! 저의 종자 맥도귈이었었지요.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227958","time":"2026-08-14T03:37:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”맞아! 맥도귈!“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227959","time":"2026-08-14T03:38:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”여이, 그동안 나도 내 나름대로 주변 사람들한테 무지하게 물어보고 다녔는데 말이야…“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227960","time":"2026-08-14T03:38:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”아무래도 서쪽엔 없는 것 같아, 여이!“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227961","time":"2026-08-14T03:38:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”다들 잘 모르더라고? 서쪽에 눌러붙어서 살아가는 녀석들이 모른다면야 없는거겠지~“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227962","time":"2026-08-14T03:39:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아, 공주님 덕분에 서쪽에 저의 종자가 없다는 소중 한 정보를 얻을 수 있었나이니! 감사합니다 공주님! 이 은혜는 그 무엇으로도 보답을 해 드릴 수 없겠나이니... 이 제가 어찌 보답을 해 드려야 하겠습니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227963","time":"2026-08-14T03:40:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”여이, 보답은 됬어. 그냥 그 맥도귈이라는 녀석이 무사한 동안에 빨리 찾기를 바라기나 하나고~”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227964","time":"2026-08-14T03:40:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“이 세상은 말이야, 우리같이 단단한 녀석들한테는야 별거 없지만…”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227965","time":"2026-08-14T03:40:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…아닌 애들한테는 또 많이 버거운 모양이더라고.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227966","time":"2026-08-14T03:41:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"물론이옵니다! 저의 종자 수색은 결코 끝나지 않을 것이오니! 허나, 저의 종자는 저와 같이 공주님의 말씀처럼 나약 한 자가 아니옵니다. 저는 저의 종자가 멀쩡하고, 또 저와 비슷하게 그 또한 저를 찾고 있다고 생각을 하고 있나이니. 아직 첫 술도 뜨지 않았는데 어찌 걱정부터 할 수 있겠나이까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227967","time":"2026-08-14T03:42:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”하하하, 그런건가~“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227968","time":"2026-08-14T03:43:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그렇다면 그런거지! 그래, 그 튼튼하고 힘찬 맥도귈이라는 녀석이 외롭게 경을 기다리는 시간이 적어지도록, 노력해보자고~ 그게 내가 바라는거야.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227969","time":"2026-08-14T03:43:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"부정적인 생각은 그 자체로도 일어나지 않을 일을 만드노니. 오로지 긍정적인 생각을 통해 더 나은 미래를 만들어야만 할 터이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227970","time":"2026-08-14T03:43:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이~! 명심할게~”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227971","time":"2026-08-14T03:43:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"역시, 공주님께서는 어찌도 이리 착한 생각을 가지고 계실련지!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227972","time":"2026-08-14T03:43:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그러고 보니 말이야.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227973","time":"2026-08-14T03:44:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“뻬르난떼 경은 그 맥도귈이라는 녀석을 많이 믿나봐? 그리 큰 걱정도 없는거 같고 말이지.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227974","time":"2026-08-14T03:44:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"맞습니다! 저의 종자가 됄 자격이 있는 녀석이었으니. 어찌 걱정을 할 수가 있겠습니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227975","time":"2026-08-14T03:46:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“오오오~ 멋지네, 확실히 굉장하겠어.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227976","time":"2026-08-14T03:46:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 미안하네… 아까부터 혼자 생각이 많아져서는 말이야, 자꾸 약한 소리나 해대고.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227977","time":"2026-08-14T03:47:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"그것을 미연에 방지하기 위하여 이 제가 있는 것이 아니겠습니까? 자고로 편력 기사란 건강한 정신에 건강한 육체 또한 깃들어 있나이니. 편력 기사와 함께 한다면 함께 하고 있는 사람들 조차 건강 해지고, 또 정신이 강인 해 지는 법이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227978","time":"2026-08-14T03:48:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 자세를 조금 고쳐앉았다. 여느때와 같이 당당하게, 가슴을 펴고 앉기 보다는 어째 조금 웅크린 듯한 자세이다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0227979","time":"2026-08-14T03:48:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“멋지네…“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227980","time":"2026-08-14T03:49:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"또 다른 고민 거리가 있으시다면 저에게 말씀을 해 주시길 바라옵니다. 저는 편력 기사이자 최고의 고민 해결사 이기도 하오니깐 말이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227981","time":"2026-08-14T03:49:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"허나, 없으시다면 저와 함께 저 달빛과 별빛들을 바라보며 이야기를 하심이 어떠하시겠습니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227982","time":"2026-08-14T03:50:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“하하하하, 그게 뭐야! 이렇게만 보면 어디 못하는게 진짜 없는 거 같구만~”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227983","time":"2026-08-14T03:50:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“고민? 까지 일려나~“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227984","time":"2026-08-14T03:50:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"하하! 그것이 바로 편력 기사라는 직책에 담겨진 무게이옵니다!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227985","time":"2026-08-14T03:50:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그냥 다 지나간 얘기인걸. 그렇게 유쾌한 것도 아니라고?”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227986","time":"2026-08-14T03:51:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“어엑, 그렇다기에는 아까부터 내가 너무 땅굴을 팠네…”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227987","time":"2026-08-14T03:51:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"허나, 고통은 함께 나누면 아주 가벼운 모래알처럼 흩어지는 법이옵니다. 저는 진실 됀 이야기던, 가벼운 이야기던간에 상관하지 않습니다. 즐거운 이야기는 배가 되는 법이오니까 말이지요!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227988","time":"2026-08-14T03:52:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그런건가…\n\n…그런건가~!!”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227989","time":"2026-08-14T03:53:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 신음을 내뱉듯이 무거운 숨을 전부 끄집어 뱉어버렸습니다. 어째 당장은 그리 지나간 날들을 걱정할 필요가 없어보입니다.\n게다가, 지금이 아니더라도 언제든 자신의 이야기를 경이라면 들어줄 것 같으니, 우선은 저 멀리 던져버릴까 합니다~","characters":["P-6a1a99e98a44"]},{"id":"RP-0227990","time":"2026-08-14T03:54:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이~! 그럼 말이야 경, 적당한 이야깃거리라도 있나?”","characters":["P-6a1a99e98a44"]},{"id":"RP-0227991","time":"2026-08-14T03:54:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"옆에서 조용히 언제 시킨 것인지 모를 감자 샐러드를 쿰척쿰척 먹고 있다.","characters":["P-f6e62ae5e46d"]},{"id":"RP-0227992","time":"2026-08-14T03:55:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"음... 허나, 안타깝게도 저는 하암... 삼일을 연속으로 잠을 자지 않은 탓에 피곤을 느끼고 있는 바람에 더이상의 이야깃거리가 없게 돼 버렸나이니. 이는 저의 불찰! 꼭 저의 모험담 이야기들을 기억 해낼 수 있겠금 정신력을 기르도록 하겠나이다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227993","time":"2026-08-14T03:56:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”어엥?? 여이, 그런 몸으로 주점에서 노래까지 부르다 온거냐고!“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227994","time":"2026-08-14T03:56:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”안되겠는걸, 경은 어서 들어가서 자!“","characters":["P-6a1a99e98a44"]},{"id":"RP-0227995","time":"2026-08-14T03:56:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"허나, 강인한 정신력 또한 편력 기사의 덕목이옵니다!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227996","time":"2026-08-14T03:56:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"대단한거 같다네 그런 정신력을 지니고 있다니...그대는 진정한 기사인거 같다네!\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0227997","time":"2026-08-14T03:56:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아, 공주님께서 그리 명령하신다면 들어야만 할 터...\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227998","time":"2026-08-14T03:56:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"역시, 진정한 기사는 진정한 기사를 알아보는 법이노니. 그대 또한 필히 진정한 기사일 터.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0227999","time":"2026-08-14T03:57:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"오… 기사 블루투스…","characters":["P-6a1a99e98a44"]},{"id":"RP-0228000","time":"2026-08-14T03:57:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"근데 허그 경이 공주...인가? 허그 경 일국의 공주 였는가?\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228001","time":"2026-08-14T03:57:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"이름 모를 기사여. 그대의 이름은 무엇이오?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0228002","time":"2026-08-14T03:57:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"본인의 이름은 얀이라 한다네...귀족 출신이여서 성은 있긴하드만 편하게 얀이라 부르시게나\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228003","time":"2026-08-14T03:57:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"물론, 그녀는 공주요. 어찌 이리도 아리따우신 분을 공주님이라 부르지 아니 할 수가 있겠소?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0228004","time":"2026-08-14T03:58:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“아하이 경 진짜! 졸려서 이러나봐?”","characters":["P-6a1a99e98a44"]},{"id":"RP-0228005","time":"2026-08-14T03:58:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아! 성을 알려주지 않을 정도로 베일에 싸인 귀족이라! 이는 필히 그 과거사에 수 많은 일들이 있었다는 증거일 터. 언젠가는 그대의 모험담을 듣고 싶구려.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0228006","time":"2026-08-14T03:58:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"아 그런 것인가? 아리따운...허그 경이 다른 이들의 비해 아름답기는 하니 이해 못할 것은 아닌거 같다네\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228007","time":"2026-08-14T03:58:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"본인도 그대의 이야기를 언젠간 들어보고 싶다네 방금 전 노래 한 곡조도 꽤나 인상 깊었다 생각한다네\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228008","time":"2026-08-14T03:59:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"뻬르난떼는 허그를 이해하지 못하겠다는 듯한 눈빛으로 쳐다봤다....\n\n그야 안 졸릴때에도 이랬으니.","characters":["P-1a1afae9c8db"]},{"id":"RP-0228009","time":"2026-08-14T03:59:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"그럼 본인이 그대의 이름을 물어보아도 되겠는가?\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228010","time":"2026-08-14T03:59:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아, 기사들끼리 통하는구려. 내, 언젠가는 그대에게 나의 사랑하는 연인(미정)을 떠오르며 쓴 자작시를 낭송 해 드리리라.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0228011","time":"2026-08-14T03:59:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"아무리 그래도 언제까지 하는건데 경… 이라는 눈빛입니다…","characters":["P-6a1a99e98a44"]},{"id":"RP-0228012","time":"2026-08-14T04:00:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"어허 기사의 신념은 일국의 왕도 꺽을 수 없는법","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228013","time":"2026-08-14T04:00:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"라이 라이 차차차!!","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228014","time":"2026-08-14T04:00:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"기사 얀이여. 나의 이름은 돈 뻬르난떼 데 일리아이고, 루밍루꼬 가문의 기사이며, 편력 기사라는 중요한 직책을 맡고 있나이다.\"\n\n물론, 루밍루꼬라는 가문은 이 세상에 없었겠지만 말이다...","characters":["P-1a1afae9c8db"]},{"id":"RP-0228015","time":"2026-08-14T04:01:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"루밍루꼬 가문 말인가?\"\n\n잠시 그런 가문이 있었는가 하고 떠올려 보았지만 딱히 생각나는 가문은 없었다. 뭐 이 대륙에 가문이 몇천개가 있는데...","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228016","time":"2026-08-14T04:01:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"처음 들어보네만 그대의 행색과 아우라를 보아하니 명예 높은 가문 출신인가 보네!\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228017","time":"2026-08-14T04:01:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아무튼, 나는 가델랏 공주님의 명에 따라 숙면을 취하러 갈 것이노니. 나중에 꼭 그대와 만나 그대의 이야기를 듣도록 하겠소. 이는 나의 약속이며, 맹세이자, 이 자리에서 하는 서약이노니.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0228018","time":"2026-08-14T04:01:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"여기 멍청이 기사 하나 추가요.","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228019","time":"2026-08-14T04:02:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 그런 둘을 지잉… 바라봅니다.\n…기사끼리는 텔레파시가 통하는건가…!","characters":["P-6a1a99e98a44"]},{"id":"RP-0228020","time":"2026-08-14T04:02:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아, 이 사실을 이리도 쉽게 알아차리는 것을 보아하니 그대 역시도 나와 같이 위대한 기사임이 분명 할 터! 그대 또한 편력 기사 인 것이오?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0228021","time":"2026-08-14T04:03:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"본인은 섬기는 자가 있다ㄴ...아니 있었다네 그리고 주군을 찾고 있으니 방황을 하는 것은 아니라네 그저 주군을 다시 찾고 있을 뿐이라네\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228022","time":"2026-08-14T04:03:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"아쎄이! 너도 어서 기사단에 합류해라아!","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228023","time":"2026-08-14T04:03:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"크아아악 난 사냥꾼이란 말이다","characters":["P-6a1a99e98a44"]},{"id":"RP-0228024","time":"2026-08-14T04:03:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아, 그대는 주군을 찾고 있구려. 나는 나의 잃어버린 종자 맥도귈을 찾고 있소. 어찌도 이리 비슷한 처지의 기사와 만났는가! 아무튼, 나는 이제 진짜로 가델랏 공주님의 명에 따라 숙면을 취하러 가기로 하겠소.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0228025","time":"2026-08-14T04:04:00+09:00","room":"RP","name":"진행 / 주점 주인 / 돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"뻬르난떼는 허그에게 손을 흔들며, 자신의 방으로 향했다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0228026","time":"2026-08-14T04:04:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이~! 잘 들어가고~”","characters":["P-6a1a99e98a44"]},{"id":"RP-0228027","time":"2026-08-14T04:04:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그도 손을 흔듭니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0228028","time":"2026-08-14T04:04:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…음…“","characters":["P-6a1a99e98a44"]},{"id":"RP-0228029","time":"2026-08-14T04:04:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그럼 얀씨, 우리도 들어가봐야지?“","characters":["P-6a1a99e98a44"]},{"id":"RP-0228030","time":"2026-08-14T04:05:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그거 다 먹고 들어갈거면 그러고.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0228031","time":"2026-08-14T04:05:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"잘가시게나!\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228032","time":"2026-08-14T04:05:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"입에 남은 음식을 다 털어 넣고는 오물 오물 거렸다. 이상하게 안에 얼굴은 보이지 않는 걸까?","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228033","time":"2026-08-14T04:05:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"그러면 가세나 다 먹었다네!\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228034","time":"2026-08-14T04:06:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”여이, 잠 잘 시간이다~“","characters":["P-6a1a99e98a44"]},{"id":"RP-0228035","time":"2026-08-14T04:06:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"꿈으로 부디 감자꿈 꾸시게나\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228036","time":"2026-08-14T04:06:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"🥔를 건낸다.","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228037","time":"2026-08-14T04:07:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그래, 얀씨가 그렇지 뭐.“\n\n🥔를 받는다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0228038","time":"2026-08-14T04:07:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그럼 그쪽은… 음…“","characters":["P-6a1a99e98a44"]},{"id":"RP-0228039","time":"2026-08-14T04:08:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”아, 커~다란 몬스터한테 깔리는 꿈 꾸자고!”\n\n이야 얼마나 좋은 꿈이란 말인가!","characters":["P-6a1a99e98a44"]},{"id":"RP-0228040","time":"2026-08-14T04:08:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"음...기왕이면 갑옷 입은 몬스터가 좋을꺼 같다네\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228041","time":"2026-08-14T04:08:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 멋지구만~”","characters":["P-6a1a99e98a44"]},{"id":"RP-0228042","time":"2026-08-14T04:08:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"\"아니면 명예를 중시하는 갑옷을 입은 몬스터나...\"","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228043","time":"2026-08-14T04:09:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"예를 들어서 감자를 권하는 그런 괴물을 떠올린다. 나쁘지 않을 수도?","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228044","time":"2026-08-14T04:09:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“하하하, 아무튼 들어가고. 나도 가볼게~”\n\n허그는 그렇게 기숙사 3층으로 올라갑니다…","characters":["P-6a1a99e98a44"]},{"id":"RP-0228045","time":"2026-08-14T04:09:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-6a1a99e98a44"]},{"id":"RP-0228046","time":"2026-08-14T04:09:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 8 = 8\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-0228047","time":"2026-08-14T04:09:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228048","time":"2026-08-14T04:09:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 7 = 7\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-0228049","time":"2026-08-14T04:09:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 좋은 감자 꿈을 꿨다네요~","characters":["P-6a1a99e98a44"]},{"id":"RP-0228050","time":"2026-08-14T04:10:00+09:00","room":"RP","name":"얀","profile":"얀","identity":"reviewed","type":"dialogue","body":"얀은 감자를 빼았기는 꿈을 꿨다네요","characters":["P-f6e62ae5e46d"]},{"id":"RP-0228051","time":"2026-08-14T04:10:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"끗!","characters":["P-6a1a99e98a44"]},{"id":"RP-0228052","time":"2026-08-14T04:10:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6a1a99e98a44"]},{"id":"RP-0228053","time":"2026-08-14T04:10:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
